"""Project model installation from generated bytes; no network access."""

import hashlib
import importlib.util
import io
import json
from pathlib import Path

import pytest

SCRIPT = Path(__file__).resolve().parents[1] / "scripts/download_models.py"
SPEC = importlib.util.spec_from_file_location("download_models", SCRIPT)
download = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(download)


def index(tmp_path, files):
    spec = {
        "repository": "generated/models",
        "revision": "main",
        "models": [
            {"path": path, "sha256": hashlib.sha256(data).hexdigest()}
            for path, data in files.items()
        ],
    }
    path = tmp_path / "project_models.json"
    path.write_text(json.dumps(spec), encoding="utf-8")
    return path


def opener(served, requested):
    def open_url(url, timeout):
        requested.append(url)
        return io.BytesIO(served[url.rsplit("/main/", 1)[1]])

    return open_url


def test_installs_verifies_and_skips_present_models(tmp_path):
    files = {"events.pt": b"generated event", "reid/osnet.pth": b"generated reid"}
    spec, folder, requested = index(tmp_path, files), tmp_path / "weights", []
    served = {
        "events.pt": files["events.pt"],
        "reid/osnet.pth": files["reid/osnet.pth"],
    }
    assert download.project_models(folder, spec, opener(served, requested)) == list(
        files
    )
    assert (folder / "reid/osnet.pth").read_bytes() == b"generated reid"
    assert (
        requested[0] == "https://huggingface.co/generated/models/resolve/main/events.pt"
    )
    download.project_models(folder, spec, opener(served, requested))
    assert len(requested) == 2


def test_rejects_changed_download_and_local_file(tmp_path):
    spec, folder = index(tmp_path, {"events.pt": b"expected"}), tmp_path / "weights"
    with pytest.raises(RuntimeError, match="pinned checksum"):
        download.project_models(folder, spec, opener({"events.pt": b"changed"}, []))
    assert not any(folder.iterdir())
    (folder / "events.pt").write_bytes(b"changed")
    with pytest.raises(RuntimeError, match=r"Local events.pt"):
        download.project_models(folder, spec, opener({}, []))
